            if (Abs(ix - x) == 0.5)
            {
                double u = ix;
                double v = ix - CopySign(1.0, x);
                if (Polyfill.TrailingZeroCount(Polyfill.DoubleToUInt64Bits(v)) > Polyfill.TrailingZeroCount(Polyfill.DoubleToUInt64Bits(u)))
                {
                    ix = v;
                }
            }

            return ix;
        }


        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double s, double e) fastTwoSum(double x, double y)
        {
            double s = x + y, z = s - x;
            return (s, y - z);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double s, double e) twoSum(double x, double y)
        {
            if (Abs(x) > Abs(y))
            {
                return fastTwoSum(x, y);
            }
            else
            {
                return fastTwoSum(y, x);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double s, double e) fastSum(double xh, double xl, double yh, double yl)
        {
            var (sh, sl) = fastTwoSum(xh, yh);
            return (sh, (xl + yl) + sl);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double s, double e) sumdd(double xh, double xl, double yh, double yl)
        {
            double sl, sh;
            if (Abs(xh) > Abs(yh))
            {
                (sh, sl) = fastTwoSum(xh, yh);
            }
            else
            {
                (sh, sl) = fastTwoSum(yh, xh);
            }
            sl += xl + yl;
            return (sh, sl);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double s, double e) muldd(double xh, double xl, double ch, double cl)
        {
            double ahhh = ch * xh;
            return (ahhh, (ch * xl + cl * xh) + FusedMultiplyAdd(ch, xh, -ahhh));
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double s, double e) mulddd(double x, double ch, double cl)
        {
            double ahhh = ch * x;
            return (ahhh, cl * x + FusedMultiplyAdd(ch, x, -ahhh));
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double h, double l) polydd(double xh, double xl, int n, ReadOnlySpan<double> c, double l)
        {
            int i = n - 1;
            var (ch, cl) = fastTwoSum(c[i * 2 + 0], l);
            cl += c[i * 2 + 1];

            while (--i >= 0)
            {
                (ch, cl) = muldd(xh, xl, ch, cl);
                (ch, cl) = fastSum(c[i * 2 + 0], c[i * 2 + 1], ch, cl);
            }
            return (ch, cl);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static (double h, double l) polydddfst(double x, int n, ReadOnlySpan<double> c, double l)
        {
            int i = n - 1;
            var (ch, cl) = fastTwoSum(c[i * 2 + 0], l);
            cl += c[i * 2 + 1];

            while (--i >= 0)
            {
                (ch, cl) = mulddd(x, ch, cl);
                (ch, cl) = fastSum(c[i * 2 + 0], c[i * 2 + 1], ch, cl);
            }

            return (ch, cl);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        static double polyd(double x, int n, ReadOnlySpan<double> c)
        {
            int i = n - 1;
            double ch = c[i * 2 + 0];
            while (--i >= 0)
            {
                ch = c[i * 2 + 0] + x * ch;
            }
            return ch;
        }


